"""Expected output of tests/t448_stats_dist.a: the verdict lines of the table families (the tables are regenerated by mk_t448.py) and the limits of the
distributions (support boundaries, invalid parameters), derived from the mathematical definitions with the Python standard library."""
import math, sys
from statistics import NormalDist
N = NormalDist()
out = []
for name, tol in (('normal pdf, cdf, sf', '3e-14'), ('t pdf, cdf, sf', '1e-12'), ('t pdf, cdf, sf for df 1e4 and 1e5', '1e-10'), ('chi-square pdf, cdf, sf', '1e-12'),
                  ('F pdf, cdf, sf', '1e-12'), ('gamma pdf, cdf, sf', '1e-12'), ('beta pdf, cdf, sf', '1e-12'), ('exponential pdf, cdf, sf', '1e-14'),
                  ('lognormal pdf, cdf', '1e-13'), ('normal quantile', '1e-13'), ('t quantile', '1e-11'), ('chi-square quantile', '1e-11'), ('F quantile', '1e-11'),
                  ('gamma quantile', '1e-11'), ('beta quantile', '1e-11'), ('exponential quantile', '1e-13'), ('lognormal quantile', '1e-13')):
    out.append('%s: all within %s: 1' % (name, tol))
g = lambda v: '%.10g' % v
sf10 = 0.5 * math.erfc(10 / math.sqrt(2))
z975 = N.inv_cdf(0.975)
lines = [
 ('normalPdf sigma 0', 'nan'), ('normalCdf sigma -1', 'nan'), ('normalCdf(inf)', '1'), ('normalCdf(-inf)', '0'), ('normalCdf(nan)', 'nan'),
 ('normalSf(10)', g(sf10)), ('normalLogPdf(1, 0, 2)', g(-0.5 * 0.25 - math.log(2) - 0.5 * math.log(2 * math.pi))),
 ('normalQuantile(0.975, 10, 2)', g(10 + 2 * z975)),
 ('tPdf df 0', 'nan'), ('tCdf df -1', 'nan'), ('tCdf(inf, 5)', '1'), ('tCdf(-inf, 5)', '0'), ('tCdf(0, 5)', '0.5'), ('tCdf(1.5, df inf) = normal', '0'),
 ('tSf(nan, 5)', 'nan'), ('tCdf(1, 1) (Cauchy)', g(0.5 + math.atan(1) / math.pi)), ('tQuantile(0.75, 1) (Cauchy)', g(math.tan(math.pi * 0.25))),
 ('tQuantile(0, 3)', '-inf'), ('tQuantile(1, 3)', 'inf'), ('tQuantile(0.5, 3)', '0'), ('tQuantile(1.5, 3)', 'nan'), ('tQuantile(0.9, 0)', 'nan'),
 ('chi2Cdf(-1, 3)', '0'), ('chi2Sf(-1, 3)', '1'), ('chi2Pdf(0, 1)', 'inf'), ('chi2Pdf(0, 2)', '0.5'), ('chi2Pdf(0, 3)', '0'), ('chi2Pdf(-2, 3)', '0'),
 ('chi2Cdf(5, 0)', 'nan'), ('chi2Quantile(0, 4)', '0'), ('chi2Quantile(1, 4)', 'inf'), ('chi2Quantile(0.95, 1)', g(N.inv_cdf(0.975) ** 2)),
 ('fPdf(0, 1, 5)', 'inf'), ('fPdf(0, 2, 5)', '1'), ('fPdf(0, 4, 5)', '0'), ('fCdf(-1, 3, 4)', '0'), ('fCdf(inf, 3, 4)', '1'), ('fCdf(1, 0, 4)', 'nan'),
 ('fQuantile(0, 3, 4)', '0'), ('fQuantile(1, 3, 4)', 'inf'), ('fQuantile(0.95, 1, 1)', g(math.tan(math.pi * 0.475) ** 2)),
 ('gammaPdf(0, 0.5, 1)', 'inf'), ('gammaPdf(0, 1, 2)', '0.5'), ('gammaPdf(0, 2, 1)', '0'), ('gammaCdf(1, 2, 0)', 'nan'),
 ('gammaQuantile(0.5, 1, 1) = ln 2', g(math.log(2))),
 ('betaPdf(0, 0.5, 2)', 'inf'), ('betaPdf(0, 1, 3)', '3'), ('betaPdf(1, 2, 0.5)', 'inf'), ('betaPdf(1.5, 2, 2)', '0'), ('betaCdf(-1, 2, 2)', '0'),
 ('betaCdf(2, 2, 2)', '1'), ('betaQuantile(0, 2, 2)', '0'), ('betaQuantile(1, 2, 2)', '1'), ('betaQuantile(0.5, 3, 3)', '0.5'),
 ('expPdf(-1, 2)', '0'), ('expCdf(-1, 2)', '0'), ('expCdf(1e-20, 1)', g(1e-20)), ('expQuantile(1, 2)', 'inf'), ('expQuantile(0.5, 0)', 'nan'),
 ('uniformPdf(0.5, 0, 1)', '1'), ('uniformPdf(2, 0, 1)', '0'), ('uniformPdf(1, 1, 1)', 'nan'), ('uniformCdf(2.5, -2.5, 4)', g(5 / 6.5)),
 ('uniformCdf(-9, -2.5, 4)', '0'), ('uniformCdf(9, -2.5, 4)', '1'), ('uniformQuantile(0.25, -2.5, 4)', g(-2.5 + 0.25 * 6.5)),
 ('uniformQuantile(1.5, 0, 1)', 'nan'), ('lognormalCdf(0, 0, 1)', '0'), ('lognormalPdf(-1, 0, 1)', '0'), ('lognormalQuantile(0.5, 2, 1) = e^2', g(math.exp(2))),
 ('lognormalQuantile(0, 0, 1)', '0'),
]
for label, v in lines:
    out.append('%s %s' % (label, v))
sys.stdout.write('\n'.join(out) + '\n')
